PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY, names TEXT NOT NULL, category TEXT NOT NULL, price INTEGER NOT NULL CHECK(price>0), cost INTEGER NOT NULL CHECK(cost>=0), grams INTEGER NOT NULL CHECK(grams>0), stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0), active INTEGER NOT NULL DEFAULT 0, details TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY, key TEXT UNIQUE NOT NULL, fingerprint TEXT NOT NULL, token TEXT NOT NULL, phone TEXT NOT NULL, address TEXT NOT NULL, status TEXT NOT NULL, total INTEGER NOT NULL, cost INTEGER NOT NULL, created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS lines(order_id TEXT REFERENCES orders(id), product_id TEXT REFERENCES products(id), quantity INTEGER NOT NULL, price INTEGER NOT NULL, cost INTEGER NOT NULL, grams INTEGER NOT NULL, PRIMARY KEY(order_id,product_id));
CREATE TABLE IF NOT EXISTS movements(id INTEGER PRIMARY KEY, product_id TEXT REFERENCES products(id), order_id TEXT, quantity INTEGER NOT NULL, kind TEXT NOT NULL, created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS journal(id INTEGER PRIMARY KEY, order_id TEXT, account TEXT NOT NULL, amount INTEGER NOT NULL, created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, entity TEXT NOT NULL, created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS outbox(id INTEGER PRIMARY KEY, event TEXT NOT NULL, entity TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', UNIQUE(event,entity));
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
